CREATE TABLE customer (customer_id INTEGER PRIMARY KEY, name TEXT, city TEXT);
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, product TEXT, quantity INTEGER);
INSERT INTO customer VALUES (1, 'Ada Lovelace', 'Seattle');
INSERT INTO customer VALUES (2, 'Alan Turing', 'Portland');
INSERT INTO orders VALUES (100, 1, 'Widget A', 2);
INSERT INTO orders VALUES (101, 2, 'Widget B', 1);
INSERT INTO orders VALUES (102, 1, 'Gadget X', 3);
SELECT o.order_id, c.name, c.city, o.product, o.quantity
FROM orders AS o
JOIN customer AS c ON o.customer_id = c.customer_id
ORDER BY o.order_id;
